import { createContext, useCallback, useEffect, useId, useLayoutEffect, useMemo, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { isServer, useLayer } from "travel-platform";
import styles from "./Popover.module.css";
import { IconButton } from "./Button.jsx";
import { cx } from "./util.js";

const useIsomorphicLayoutEffect = isServer ? useEffect : useLayoutEffect;

const FOCUSABLE = "a[href], button:not([disabled]), input:not([disabled]), select, textarea, [tabindex]:not([tabindex='-1'])";

function usePlacement(anchorRef, panelRef, open, position) {
    const [placement, setPlacement] = useState(null);
    useIsomorphicLayoutEffect(() => {
        if (!open || !anchorRef.current || !panelRef.current)
            return;
        const anchor = anchorRef.current.getBoundingClientRect();
        const panel = panelRef.current.getBoundingClientRect();
        const viewportWidth = document.documentElement.clientWidth;
        let top = anchor.bottom + window.scrollY + 8;
        let left = position === "end" ? anchor.right - panel.width : position === "center" ? anchor.left + (anchor.width - panel.width) / 2 : anchor.left;
        left = Math.max(8, Math.min(left + window.scrollX, viewportWidth - panel.width - 8));
        if (anchor.bottom + panel.height + 8 > window.innerHeight && anchor.top > panel.height + 8)
            top = anchor.top + window.scrollY - panel.height - 8;
        setPlacement({ top: Math.round(top), left: Math.round(left), arrow: Math.round(anchor.left + anchor.width / 2 - left) });
    }, [open, position, anchorRef, panelRef]);
    return placement;
}

function useDismiss(open, onClose, panelRef, anchorRef) {
    useEffect(() => {
        if (!open)
            return undefined;
        const onKeyDown = (event) => {
            if (event.key === "Escape")
                onClose("escape");
        };
        const onPointerDown = (event) => {
            if (!panelRef.current?.contains(event.target) && !anchorRef?.current?.contains(event.target))
                onClose("outside");
        };
        document.addEventListener("keydown", onKeyDown);
        document.addEventListener("mousedown", onPointerDown);
        return () => {
            document.removeEventListener("keydown", onKeyDown);
            document.removeEventListener("mousedown", onPointerDown);
        };
    }, [open, onClose, panelRef, anchorRef]);
}

function useInitialFocus(open, panelRef, returnFocusRef) {
    useEffect(() => {
        if (!open || !panelRef.current)
            return undefined;
        const previous = document.activeElement;
        const first = panelRef.current.querySelector(FOCUSABLE);
        first?.focus({ preventScroll: true });
        return () => (returnFocusRef?.current ?? previous)?.focus?.({ preventScroll: true });
    }, [open, panelRef, returnFocusRef]);
}

export function Popover({ open, anchorRef, onClose, position = "start", title, closeLabel = "Close", width, className, children, testId }) {
    const layer = useLayer();
    const panelRef = useRef(null);
    const id = useId();
    const placement = usePlacement(anchorRef, panelRef, open, position);
    useDismiss(open, onClose, panelRef, anchorRef);
    useInitialFocus(open, panelRef, anchorRef);
    useEffect(() => {
        if (!open || !layer)
            return undefined;
        layer.push(id);
        return () => layer.pop(id);
    }, [open, layer, id]);
    if (!open || !layer)
        return null;
    return createPortal(
        <div
            ref={panelRef}
            role="dialog"
            aria-modal="false"
            aria-labelledby={title ? `${id}-title` : undefined}
            className={cx(styles.popover, placement && styles.placed, className)}
            style={{ "--tk_popover-top": `${placement?.top ?? 0}px`, "--tk_popover-left": `${placement?.left ?? 0}px`, "--tk_popover-arrow": `${placement?.arrow ?? 24}px`, "--tk_popover-width": width ? `${width}px` : undefined }}
            data-testid={testId}
        >
            <span className={styles.arrow} aria-hidden="true" />
            {title ? (
                <div className={styles.header}>
                    <div id={`${id}-title`} className={styles.title}>{title}</div>
                    <IconButton icon="close" label={closeLabel} size="small" onClick={() => onClose("close")} data-testid={testId && `${testId}-close`} />
                </div>
            ) : null}
            <div className={styles.content}>{children}</div>
        </div>,
        layer.getContainer(),
    );
}

export function Dialog({ open, onClose, title, closeLabel = "Close", footer, children, testId }) {
    const layer = useLayer();
    const panelRef = useRef(null);
    const id = useId();
    useDismiss(open, onClose, panelRef, null);
    useInitialFocus(open, panelRef, null);
    const trapFocus = useCallback((event) => {
        if (event.key !== "Tab" || !panelRef.current)
            return;
        const focusable = [...panelRef.current.querySelectorAll(FOCUSABLE)];
        if (!focusable.length)
            return;
        const first = focusable[0];
        const last = focusable[focusable.length - 1];
        if (event.shiftKey && document.activeElement === first) {
            event.preventDefault();
            last.focus();
        } else if (!event.shiftKey && document.activeElement === last) {
            event.preventDefault();
            first.focus();
        }
    }, []);
    if (!open || !layer)
        return null;
    return createPortal(
        <div className={styles.overlay}>
            <div ref={panelRef} role="dialog" aria-modal="true" aria-labelledby={`${id}-title`} className={styles.dialog} onKeyDown={trapFocus} data-testid={testId}>
                <div className={styles.header}>
                    <div id={`${id}-title`} className={styles.dialogTitle}>{title}</div>
                    <IconButton icon="close" label={closeLabel} onClick={() => onClose("close")} data-testid={testId && `${testId}-close`} />
                </div>
                <div className={styles.content}>{children}</div>
                {footer ? <div className={styles.footer}>{footer}</div> : null}
            </div>
        </div>,
        layer.getContainer(),
    );
}

const TooltipContext = createContext(null);

export function Tooltip({ text, children }) {
    const [open, setOpen] = useState(false);
    const anchorRef = useRef(null);
    const id = useId();
    const show = useCallback(() => setOpen(true), []);
    const close = useCallback(() => setOpen(false), []);
    const value = useMemo(() => ({ id, open }), [id, open]);
    return (
        <TooltipContext.Provider value={value}>
            <span ref={anchorRef} className={styles.tooltipAnchor} aria-describedby={open ? id : undefined} onMouseEnter={show} onMouseLeave={close} onFocus={show} onBlur={close}>
                {children}
                <Popover open={open} anchorRef={anchorRef} onClose={close} position="center" className={styles.tooltip}>{text}</Popover>
            </span>
        </TooltipContext.Provider>
    );
}
